 function addPlayer(e:FormEvent){e.preventDefault();const cleanName=name.trim();const digits=phone.trim();if(!cleanName)return;if(!/^[6-9][0-9]{9}$/.test(digits)){setPhoneError("Enter a valid 10-digit mobile number. This field is mandatory.");return;}const duplicate=players.some(p=>p.id!==editingPlayerId&&p.name.trim().toLowerCase()===cleanName.toLowerCase());if(duplicate){setPhoneError("This player name is already in use. Please use a unique name or add a nickname.");void Swal.fire({icon:"warning",title:"Player name already exists",text:"Please use a unique name or add a nickname (for example, Aniket Wagh / Aniket Patil) to avoid confusion when recording payments."});return;}setPhoneError("");if(editingPlayerId){setPlayers(current=>current.map(p=>p.id===editingPlayerId?{...p,name:cleanName,phone:digits}:p));void Swal.fire({toast:true,position:"top-end",icon:"success",title:"Player details updated",showConfirmButton:false,timer:1500});}else{setPlayers(current=>[...current,{id:crypto.randomUUID(),name:cleanName,phone:digits,active:true}]);}setName("");setPhone("");setEditingPlayerId("");setShowPlayer(false);localStorage.setItem("tm-player-modal-open","false");localStorage.removeItem("tm-player-draft-editing-id");localStorage.removeItem("tm-player-draft-name");localStorage.removeItem("tm-player-draft-phone");}
