 async function deletePlayer(player:Player){const result=await Swal.fire({title:"Remove "+player.name+"?",text:"This player will be removed from the active roster and cannot be selected for future sessions. Past attendance and payment history will be kept.",icon:"warning",showCancelButton:true,confirmButtonText:"Yes, remove player",cancelButtonText:"Cancel",confirmButtonColor:"#dc2626",cancelButtonColor:"#64748b",reverseButtons:true});if(!result.isConfirmed)return;setPlayers(current=>current.map(p=>p.id===player.id?{...p,active:false}:p));setAttendanceDraft(current=>current.filter(id=>id!==player.id));if(reminderPlayerId===player.id)setReminderPlayerId("");await Swal.fire({icon:"success",title:"Player removed",text:"Past records have been preserved.",timer:1500,showConfirmButton:false});}
 function addSession(e:FormEvent){e.preventDefault();const total=Number(amount), actualTurfCharges=Number(turfCharges), per=Number(contribution);if(total<=0||actualTurfCharges<=0||actualTurfCharges>total||(mode==="fund"&&per<=0))return;const values={date,venue,startTime:sessionStartTime,endTime:sessionEndTime,total,turfCharges:actualTurfCharges,mode,contribution:mode==="fund"?per:0};if(editingSessionId){setSessions(current=>current.map(s=>{if(s.id!==editingSessionId)return s;const financeChanged=s.total!==total||s.turfCharges!==actualTurfCharges||s.mode!==mode||s.contribution!==(mode==="fund"?per:0);return {...s,...values,organiserAdvanceSettled:financeChanged?false:s.organiserAdvanceSettled,organiserAdvanceSettledAt:financeChanged?undefined:s.organiserAdvanceSettledAt};}));void Swal.fire({icon:"success",title:"Changes saved",text:"Your session has been updated.",timer:1500,showConfirmButton:false});}else{const session:Session={id:crypto.randomUUID(),...values,participants:[],attendance:{}};setSessions(current=>[session,...current]);setDetailSessionId(session.id);setTab("Session details");setNotice("Session created. Add the players attending, then share the session details whenever you are ready.");}setAmount("");setTurfCharges("");setShowSession(false);setEditingSessionId("");setSessionStartTime("21:00");setSessionEndTime("00:00");}
 function openAttendance(s:Session){setAttendanceSessionId(s.id);setAttendanceDraft(s.participants||[]);setQuickPlayerName("");setQuickPlayerPhone("");setShowQuickPlayerForm(false);}
 function addPlayerFromAttendance(){const playerName=quickPlayerName.trim();const digits=quickPlayerPhone.trim();if(!playerName)return;if(!/^[6-9][0-9]{9}$/.test(digits)){setQuickPhoneError("Enter a valid 10-digit mobile number. This field is mandatory.");return;}setQuickPhoneError("");const duplicate=players.some(p=>p.name.trim().toLowerCase()===playerName.toLowerCase());if(duplicate){setQuickPhoneError("This player name is already in use. Please use a unique name or add a nickname.");void Swal.fire({icon:"warning",title:"Player name already exists",text:"Please use a unique name or add a nickname to avoid confusion when recording payments."});return;}setQuickPhoneError("");const player:Player={id:crypto.randomUUID(),name:playerName,phone:digits};setPlayers(current=>[...current,player]);setAttendanceDraft(current=>[...current,player.id]);setQuickPlayerName("");setQuickPlayerPhone("");setShowQuickPlayerForm(false);Swal.fire({toast:true,position:"top-end",icon:"success",title:"Player added to roster",showConfirmButton:false,timer:1600});}
 function saveAttendance(e:FormEvent){e.preventDefault();const id=attendanceSessionId;const names=attendanceDraft.map(pid=>players.find(p=>p.id===pid)?.name.trim().toLowerCase()).filter((name):name is string=>!!name);if(new Set(names).size!==names.length){void Swal.fire({icon:"warning",title:"Duplicate player names in this session",text:"Please keep every player name unique. Edit one of the names or add a nickname before saving attendance, so payments are recorded against the correct person."});return;}setSessions(current=>current.map(s=>s.id===id?{...s,participants:attendanceDraft,attendance:Object.fromEntries(attendanceDraft.map(pid=>[pid,1]))}:s));setAttendanceSessionId("");resetShareProgress();setAnnouncementSessionId(attendanceDraft.length>0?id:"");}
 function approveSessionPayment(s:Session,player:Player){const due=amountDueForSession(player.id,s.id);if(due<=0){void Swal.fire({icon:"info",title:"Payment already complete"});return;}void Swal.fire({title:"Approve payment?",html:"Record <b>"+money(due)+"</b> received from "+player.name+" for "+s.venue+"?",icon:"question",showCancelButton:true,confirmButtonText:"Yes, record payment"}).then(result=>{if(result.isConfirmed){setPayments(current=>[{id:crypto.randomUUID(),playerId:player.id,amount:due,date:new Date().toISOString().slice(0,10),note:"Approved by organiser",method:"UPI",sessionId:s.id},...current]);setSessions(current=>current.map(x=>x.id===s.id?{...x,organiserAdvanceSettled:false,organiserAdvanceSettledAt:undefined}:x));void Swal.fire({icon:"success",title:"Payment recorded",timer:1400,showConfirmButton:false});}});}
 function editSession(s:Session){setEditingSessionId(s.id);setDate(s.date);setVenue(s.venue);setSessionStartTime(s.startTime||"21:00");setSessionEndTime(s.endTime||"00:00");setAmount(String(s.total));setTurfCharges(String(s.turfCharges??s.total));setMode(s.mode);setHasCricketFund(s.mode==="fund");setContribution(String(s.contribution||250));setShowSession(true);}
 async function deleteSession(s:Session){const result=await Swal.fire({title:"Delete this session?",text:"Payments recorded against this session will also be deleted. This action cannot be undone.",icon:"warning",showCancelButton:true,confirmButtonText:"Yes, delete session",cancelButtonText:"Keep session",confirmButtonColor:"#dc2626",cancelButtonColor:"#64748b",reverseButtons:true});if(!result.isConfirmed)return;setSessions(current=>current.filter(x=>x.id!==s.id));setPayments(current=>current.filter(p=>p.sessionId!==s.id));if(announcementSessionId===s.id)setAnnouncementSessionId("");await Swal.fire({icon:"success",title:"Session deleted",text:"The session has been removed.",timer:1500,showConfirmButton:false});}
 function addPayment(e:FormEvent){e.preventDefault();const n=Number(payAmount);if(hasDuplicatePaymentNames&&!editingPaymentId){void Swal.fire({icon:"warning",title:"Duplicate player names in this session",text:"Please rename one player or add a nickname before recording payment."});return;}if(!payPlayer||!paySession||n<=0)return;const record:Payment={id:editingPaymentId||crypto.randomUUID(),playerId:payPlayer,amount:n,date:new Date().toISOString().slice(0,10),note:payNote,method:payMethod,sessionId:paySession};setPayments(current=>editingPaymentId?current.map(p=>p.id===editingPaymentId?{...p,...record,date:p.date}:p):[record,...current]);setSessions(current=>current.map(x=>x.id===paySession?{...x,organiserAdvanceSettled:false,organiserAdvanceSettledAt:undefined}:x));setPayAmount("");setPayNote("");setEditingPaymentId("");void Swal.fire({toast:true,position:"top-end",icon:"success",title:editingPaymentId?"Payment updated":"Payment recorded",showConfirmButton:false,timer:1500});}
 function editPayment(p:Payment){setEditingPaymentId(p.id);setPaySession(p.sessionId);setPayPlayer(p.playerId);const player=players.find(x=>x.id===p.playerId);setPayPlayerName(player?.name||"");setPayPlayerPhone(p.playerId);setPayAmount(String(p.amount));setPayNote(p.note);setPayMethod(p.method);setTab("Payments");}
 async function deletePayment(p:Payment){const result=await Swal.fire({title:"Delete payment record?",text:"This will reverse the recorded payment and increase the player's outstanding balance.",icon:"warning",showCancelButton:true,confirmButtonText:"Delete payment",cancelButtonText:"Cancel",confirmButtonColor:"#dc2626"});if(!result.isConfirmed)return;setPayments(current=>current.filter(x=>x.id!==p.id));setSessions(current=>current.map(x=>x.id===p.sessionId?{...x,organiserAdvanceSettled:false,organiserAdvanceSettledAt:undefined}:x));if(editingPaymentId===p.id){setEditingPaymentId("");setPayPlayer("");setPayAmount("");setPayNote("");}void Swal.fire({icon:"success",title:"Payment deleted",timer:1300,showConfirmButton:false});}
 function expectedForPlayer(s:Session,playerId:string){if(!s.participants.includes(playerId))return 0;if(s.mode==="fund")return s.contribution;const count=s.participants.length;return count?s.total/count:0;}
 function sessionReceived(s:Session){return payments.filter(p=>p.sessionId===s.id).reduce((sum,p)=>sum+p.amount,0);}
 function sessionOrganiserAdvance(s:Session){if(s.mode!=="fund"||!s.participants.length)return 0;return s.organiserAdvanceSettled?(s.organiserAdvanceSettledAmount??Math.max(0,s.total-sessionReceived(s))):Math.max(0,s.total-sessionReceived(s));}
 function fundBalanceAfterSession(s:Session){const relevant=sessions.filter(x=>x.mode==="fund"&&x.date<=s.date),ids=new Set(relevant.map(x=>x.id));const credits=payments.filter(p=>ids.has(p.sessionId)).reduce((n,p)=>n+p.amount,0),expenses=relevant.reduce((n,x)=>n+x.total,0),manual=fundTransactions.filter(t=>t.date<=s.date).reduce((n,t)=>n+(t.type==="Contribution"?t.amount:-t.amount),0),advances=relevant.filter(x=>!x.organiserAdvanceSettled).reduce((n,x)=>n+sessionOrganiserAdvance(x),0);return openingFund+credits-expenses+manual+advances;}
 function fundBalanceBeforeSession(s:Session){const prior=sessions.filter(x=>x.mode==="fund"&&x.date<s.date),ids=new Set(prior.map(x=>x.id));const credits=payments.filter(p=>ids.has(p.sessionId)&&p.date<s.date).reduce((n,p)=>n+p.amount,0),expenses=prior.reduce((n,x)=>n+x.total,0),manual=fundTransactions.filter(t=>t.date<s.date).reduce((n,t)=>n+(t.type==="Contribution"?t.amount:-t.amount),0),advances=prior.reduce((sum,x)=>{const settledBefore=x.organiserAdvanceSettledAt?x.organiserAdvanceSettledAt<s.date:false;if(settledBefore)return sum;const received=payments.filter(p=>p.sessionId===x.id&&p.date<s.date).reduce((n,p)=>n+p.amount,0);return sum+Math.max(0,x.total-received);},0);return openingFund+credits-expenses+manual+advances;}
 function sessionFundSurplus(s:Session){return s.mode==="fund"?Math.max(0,sessionReceived(s)-s.total):0;}
 function latestSessionForPlayer(playerId:string){return [...sessions].filter(s=>s.participants.includes(playerId)).sort((a,b)=>b.date.localeCompare(a.date))[0];}
 function amountDueForSession(playerId:string,sessionId:string){const s=sessions.find(x=>x.id===sessionId);if(!s)return 0;const expected=expectedForPlayer(s,playerId);const paid=payments.filter(p=>p.playerId===playerId&&p.sessionId===sessionId).reduce((n,p)=>n+p.amount,0);return Math.max(0,expected-paid);}
 function sessionOutstanding(s:Session){return s.participants.reduce((n,id)=>n+amountDueForSession(id,s.id),0);}
 function sessionPaid(s:Session,playerId:string){return payments.filter(p=>p.sessionId===s.id&&p.playerId===playerId).reduce((total,p)=>total+p.amount,0);}
 useEffect(()=>{if(!sessions.length)return;if(!paySession){const latest=[...sessions].sort((a,b)=>b.date.localeCompare(a.date))[0];setPaySession(latest.id);}},[sessions,paySession]);
 
 useEffect(()=>{if(!payPlayer||!paySession||editingPaymentId)return;const due=amountDueForSession(payPlayer,paySession);setPayAmount(due>0?String(Math.round(due*100)/100):"");},[payPlayer,paySession,sessions,payments,editingPaymentId]);
 function savePayeeDetails(e:FormEvent){e.preventDefault();const cleanName=payeeDraft.trim(),cleanUpi=upiDraft.trim();if(!cleanName||!cleanUpi){void Swal.fire({icon:"warning",title:"Complete payment details",text:"Enter both the payee name and UPI ID."});return;}setPayeeName(cleanName);setUpiId(cleanUpi);void Swal.fire({icon:"success",title:"Payment details updated",text:"New UPI links will use these details.",timer:1500,showConfirmButton:false});}
 function saveFundManagerDetails(e:FormEvent){e.preventDefault();const cleanName=fundManagerNameDraft.trim(),digits=fundManagerPhoneDraft.replace(/\D/g,"");if(!cleanName||!/^[6-9][0-9]{9}$/.test(digits)){void Swal.fire({icon:"warning",title:"Check fund manager details",text:"Enter a name and a valid 10-digit Indian mobile number."});return;}setFundManagerName(cleanName);setFundManagerPhone(digits);localStorage.setItem("tm-fund-manager-name",cleanName);localStorage.setItem("tm-fund-manager-phone",digits);void Swal.fire({icon:"success",title:"Fund manager details updated",timer:1400,showConfirmButton:false});}
  function remindFundManagerForSession(s:Session){const amount=sessionOrganiserAdvance(s);if(amount<=0||s.organiserAdvanceSettled)return;const payload={n:"Cricket fund settlement",a:amount.toFixed(2),u:upiId,p:payeeName,t:"TurfMate fund settlement - "+s.venue+" - "+s.date};const bytes=new TextEncoder().encode(JSON.stringify(payload));let binary="";bytes.forEach(byte=>binary+=String.fromCharCode(byte));const token=btoa(binary).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"");const qrLink=window.location.origin+"/p/"+token;const message="Hi "+fundManagerName+" 👋\n\nPlease settle the organiser advance for this TurfMate cricket session. 🏏\n\n*Session:* "+s.venue+"\n*Date:* "+s.date+"\n*Amount to transfer:* "+money(amount)+"\n\nPlease use this payment QR. The amount and settlement note are prefilled.\n"+qrLink+"\n\nI’ll mark this session’s organiser advance as settled in TurfMate once the transfer is received. Thank you!";openWhatsappMessage(message,fundManagerPhone);}
 function settleOrganiserAdvance(s:Session){if(s.organiserAdvanceSettled)return;const outstanding=sessionOutstanding(s);if(outstanding>0){void Swal.fire({icon:"warning",title:"Player contributions are still pending",text:"Collect all player contributions before settling the organiser advance. Remaining amount: "+money(outstanding)+"."});return;}const advance=sessionOrganiserAdvance(s);if(!advance)return;if(fundBalance-advance<0){void Swal.fire({icon:"warning",title:"Insufficient cricket fund",text:"The available fund balance is not enough to settle this organiser advance yet."});return;}void Swal.fire({title:"Mark organiser advance as settled?",text:"All player contributions are received. Record "+money(advance)+" as reimbursed to the organiser from the cricket fund.",icon:"question",showCancelButton:true,confirmButtonText:"Yes, mark settled"}).then(result=>{if(result.isConfirmed){setSessions(current=>current.map(x=>x.id===s.id?{...x,organiserAdvanceSettled:true,organiserAdvanceSettledAt:new Date().toISOString().slice(0,10),organiserAdvanceSettledAmount:advance}:x));void Swal.fire({icon:"success",title:"Advance settled",timer:1400,showConfirmButton:false});}});}
 function addFundEntry(e:FormEvent){e.preventDefault();const n=Number(fundAmount);if(n<=0)return;if(fundType==="Withdrawal"&&n>fundBalance){void Swal.fire({icon:"warning",title:"Insufficient cricket fund",text:"The withdrawal cannot be greater than the current fund balance of "+money(fundBalance)+"."});return;}setFundTransactions(current=>[{id:crypto.randomUUID(),date:new Date().toISOString().slice(0,10),type:fundType,amount:n,note:fundNote.trim()},...current]);setFundAmount("");setFundNote("");void Swal.fire({icon:"success",title:fundType==="Contribution"?"Contribution added":"Withdrawal recorded",timer:1400,showConfirmButton:false});}
 function isLedgerSessionSettled(s:Session){return s.date>="2026-11-01"&&s.participants.length>0&&sessionOutstanding(s)<=0&&(sessionOrganiserAdvance(s)<=0||s.organiserAdvanceSettled);}
 function applyReportPreset(value:string){setReportPreset(value);const now=new Date(),fmt=(d:Date)=>d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");let from=new Date(now.getFullYear(),now.getMonth(),1);if(value==="previous-month")from=new Date(now.getFullYear(),now.getMonth()-1,1);else if(value==="last-3")from=new Date(now.getFullYear(),now.getMonth()-2,1);else if(value==="last-6")from=new Date(now.getFullYear(),now.getMonth()-5,1);else if(value==="year-to-date")from=new Date(now.getFullYear(),0,1);else if(value==="last-year") {from=new Date(now.getFullYear()-1,0,1);setReportEnd(fmt(new Date(now.getFullYear()-1,11,31)));}else if(value==="last-12")from=new Date(now.getFullYear(),now.getMonth()-11,1);if(value==="previous-month")setReportEnd(fmt(new Date(now.getFullYear(),now.getMonth(),0)));else if(value!=="custom"&&value!=="last-year")setReportEnd(fmt(now));if(value!=="custom")setReportStart(fmt(from));}
 function downloadReport(){
  if(!reportStart||!reportEnd||reportStart>reportEnd){void Swal.fire({icon:"warning",title:"Check report dates",text:"Please choose a valid date range."});return;}
  const settledSessions=sessions.filter(isLedgerSessionSettled).sort((a,b)=>a.date.localeCompare(b.date));
  let runningBalance=ledgerOpeningBalance;
  const ledgerRows=settledSessions.map(s=>{
   const opening=runningBalance;
   const collections=sessionReceived(s);
   const totalExpense=s.total;
   const closing=opening+collections-totalExpense;
   runningBalance=closing;
   return {session:s,opening,collections,totalExpense,closing,turfExpense:s.turfCharges??s.total,otherExpense:Math.max(0,s.total-(s.turfCharges??s.total))};
  });
  const rows=ledgerRows.filter(row=>row.session.date>=reportStart&&row.session.date<=reportEnd);
  const openingBalance=rows.length?rows[0].opening:(ledgerRows.filter(row=>row.session.date<reportStart).at(-1)?.closing??ledgerOpeningBalance);
  const closingBalance=rows.length?rows[rows.length-1].closing:openingBalance;
  if(!rows.length){void Swal.fire({icon:"info",title:"No settled sessions in this period",text:"Only sessions with all player dues cleared and any organiser advance settled are included in the report."});return;}
  const totalCollections=rows.reduce((sum,row)=>sum+row.collections,0);
  const totalExpense=rows.reduce((sum,row)=>sum+row.totalExpense,0);
  const totalTurf=rows.reduce((sum,row)=>sum+row.turfExpense,0);
  const totalOther=rows.reduce((sum,row)=>sum+row.otherExpense,0);
  const doc=new jsPDF({orientation:"landscape",unit:"mm",format:"a4"});doc.setCharSpace(0);
  const W=297,H=210,L=12,tableW=273,navy=[19,42,61] as [number,number,number],green=[24,151,105] as [number,number,number],pale=[239,247,243] as [number,number,number],ink=[43,57,72] as [number,number,number],muted=[112,127,143] as [number,number,number],white=[255,255,255] as [number,number,number];
  const setText=(rgb:[number,number,number])=>doc.setTextColor(rgb[0],rgb[1],rgb[2]);
  const fmtMoney=(value:number)=>"Rs. "+Math.round(value).toLocaleString("en-IN");
  const prettyDate=(value:string)=>new Date(value+"T00:00:00").toLocaleDateString("en-IN",{day:"2-digit",month:"short",year:"numeric"});
  let y=0;
  const header=()=>{doc.setFillColor(...navy);doc.rect(0,0,W,31,"F");doc.setFillColor(...green);doc.rect(0,30,W,2,"F");doc.setFont("helvetica","bold");doc.setFontSize(20);setText(white);doc.text("TurfMate",L,14);doc.setFont("helvetica","normal");doc.setFontSize(8);doc.text("MANHATTAN CRICKET  /  SETTLED FINANCE SUMMARY",L,22);doc.setFont("helvetica","bold");doc.setFontSize(10);doc.text("TURF SUMMARY REPORT",W-L,15,{align:"right"});};
  const footer=()=>{const pages=doc.getNumberOfPages();for(let page=1;page<=pages;page++){doc.setPage(page);doc.setDrawColor(224,231,237);doc.line(L,198,W-L,198);doc.setFont("helvetica","normal");doc.setFontSize(7);setText(muted);doc.text("Generated by TurfMate  ·  "+new Date().toLocaleDateString("en-IN"),L,203);doc.text("Page "+page+" of "+pages,W-L,203,{align:"right"});}};
  header();y=42;doc.setFont("helvetica","bold");doc.setFontSize(15);setText(navy);doc.text("Turf summary",L,y);doc.setFont("helvetica","normal");doc.setFontSize(8);setText(muted);doc.text("Period: "+prettyDate(reportStart)+" to "+prettyDate(reportEnd)+"   ·   Settled sessions only",L,y+6);y+=14;
  const cards:[string,string][]=[["SETTLED SESSIONS",String(rows.length)],["TOTAL COLLECTIONS",fmtMoney(totalCollections)],["TOTAL EXPENSES",fmtMoney(totalExpense)],["CLOSING BALANCE",fmtMoney(closingBalance)]];
  const gap=5,cw=(tableW-gap*3)/4;
  cards.forEach((card,index)=>{const x=L+index*(cw+gap);doc.setFillColor(246,248,250);doc.roundedRect(x,y,cw,19,2,2,"F");doc.setFont("helvetica","bold");doc.setFontSize(6.5);setText(muted);doc.text(card[0],x+4,y+7);doc.setFontSize(10);setText(index===3?green:navy);doc.text(card[1],x+4,y+14);});
  y+=27;
  const headers=["DATE","OPENING BALANCE","PLAYERS","TURF EXPENSE","WATER / BALLS","TOTAL EXPENSE","COLLECTIONS","TOTAL BALANCE"];
  const widths=[27,36,22,34,34,36,37,47];
  const drawTableHeader=()=>{doc.setFillColor(...navy);doc.roundedRect(L,y,tableW,10,1.5,1.5,"F");doc.setFont("helvetica","bold");doc.setFontSize(7);setText(white);let x=L;headers.forEach((label,index)=>{doc.text(label,x+2,y+6.5);x+=widths[index];});y+=10;};
  drawTableHeader();
  rows.forEach((row,index)=>{
   if(y+9>190){doc.addPage("a4","landscape");header();y=42;drawTableHeader();}
   if(index%2===0){doc.setFillColor(247,250,251);doc.rect(L,y,tableW,9,"F");}
   const cells=[prettyDate(row.session.date),fmtMoney(row.opening),String(row.session.participants.length),fmtMoney(row.turfExpense),fmtMoney(row.otherExpense),fmtMoney(row.totalExpense),fmtMoney(row.collections),fmtMoney(row.closing)];
   doc.setFont("helvetica","normal");doc.setFontSize(7);setText(ink);let x=L;
   cells.forEach((cell,cellIndex)=>{const align=cellIndex===0||cellIndex===2?"left":"right";doc.text(cell,align==="right"?x+widths[cellIndex]-2:x+2,y+6,{align});x+=widths[cellIndex];});
   doc.setDrawColor(229,235,239);doc.line(L,y+9,L+tableW,y+9);y+=9;
  });
  if(y+12>190){doc.addPage("a4","landscape");header();y=42;}
  doc.setFillColor(...pale);doc.rect(L,y,tableW,11,"F");doc.setFont("helvetica","bold");doc.setFontSize(7);setText(navy);
  const totals=["PERIOD TOTALS",fmtMoney(openingBalance),String(rows.reduce((sum,row)=>sum+row.session.participants.length,0)),fmtMoney(totalTurf),fmtMoney(totalOther),fmtMoney(totalExpense),fmtMoney(totalCollections),fmtMoney(closingBalance)];
  let x=L;totals.forEach((cell,index)=>{const align=index===0||index===2?"left":"right";doc.text(cell,align==="right"?x+widths[index]-2:x+2,y+7,{align});x+=widths[index];});
  y+=11;
  if(y+19<190){y+=5;doc.setFont("helvetica","normal");doc.setFontSize(7);setText(muted);doc.text("Opening balance carried forward from the historical ledger: "+fmtMoney(ledgerOpeningBalance)+". Additional expenses are calculated as total session expenses minus actual turf charges.",L,y+5);}
  footer();
  doc.save("TurfMate-Turf-Summary-"+reportStart+"-to-"+reportEnd+".pdf");
 }

 const reminderPlayer=activePlayers.find(p=>p.id===reminderPlayerId);
 const reminderSession=sessions.find(s=>s.id===sessionReminderId);
 const reminderSessions=reminderPlayer?(reminderSession?[reminderSession]:sessions.filter(s=>s.participants.includes(reminderPlayer.id)).sort((a,b)=>b.date.localeCompare(a.date))).filter(s=>amountDueForSession(reminderPlayer.id,s.id)>0):[];
 const reminderDue=reminderPlayer?(reminderSession?amountDueForSession(reminderPlayer.id,reminderSession.id):reminderSessions.reduce((sum,s)=>sum+amountDueForSession(reminderPlayer.id,s.id),0)):0;
 const upiPaymentUri=(amount:number,note:string)=>"upi://pay?pa="+encodeURIComponent(upiId)+"&pn="+encodeURIComponent(payeeName)+"&am="+encodeURIComponent(Math.max(0,amount).toFixed(2))+"&cu=INR&tn="+encodeURIComponent(note.slice(0,80));
